/* Deterministic lab fixtures, not a clinical classifier. Unknown input fails closed. */
(function(root){
  const normalize=s=>String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');
  const emptyFacts=()=>({age:'',pregnancy:'unknown',meds:'',conditions:'',duration:''});
  function classify(text,facts=emptyFacts(),{corrected=false}={}){
    const t=normalize(text), f={...facts};
    const age=t.match(/(\d+(?:[.,]\d+)?)\s*tuoi/);if(age&&!corrected)f.age=age[1].replace(',','.');
    if(!corrected&&/\d+\s*thang tuoi|tre so sinh/.test(t))f.age='0';
    if(!corrected&&/dang bau|mang thai|co thai|cho con bu/.test(t)&&!/khong (mang thai|co thai|cho con bu)/.test(t))f.pregnancy='yes';
    // Negated symptoms are removed; uncertain or indirect phrases still trigger a conservative escalation.
    const dangerText=t.replace(/khong (bi |co |con )?(kho tho|dau nguc|lo mo|tim tai|co giat)/g,'');
    const danger=dangerText.match(/kho tho|dau nguc|lo mo|tim tai|co giat|bat tinh|khong tho|tho khong (duoc|noi)|tho doc/);
    if(danger)return {route:'emergency',facts:f,reason:`Tin nhắn có cụm “${danger[0]}”`,rule:'T1 · dấu hiệu nguy hiểm',text:'Bạn mô tả dấu hiệu có thể nguy hiểm. Hãy gọi cấp cứu hoặc đến cơ sở cấp cứu ngay; đừng chờ dược sĩ trong chat. Mình không thể đánh giá mức độ qua tin nhắn và sẽ không gợi ý thuốc. Thông báo ưu tiên đã được tạo ở bàn dược sĩ mô phỏng, nhưng không thay thế hỗ trợ cấp cứu.'};
    if(/khang sinh|amoxicillin|augmentin|thuoc huyet ap|ke don|khong co don/.test(t))return {route:'prescription',facts:f,reason:'Yêu cầu có thuốc kê đơn hoặc kháng sinh',rule:'T1 · ngoài thẩm quyền',text:'Mình không bán, chỉ liều hay gợi ý thuốc thay thế cho thuốc kê đơn qua chat AI. Bạn có thể trao đổi với dược sĩ về bước khám và kiểm tra đơn phù hợp. Mình đã tạo yêu cầu chuyển dược sĩ mô phỏng.'};
    // Conservative demo policy, not a validated medical threshold.
    if(/\b([7-9]|[1-9]\d+)\s*(ngay|hom)|\b\d+\s*(tuan|thang)\b/.test(t+' '+normalize(f.duration)))return {route:'handoff',facts:f,reason:'Thời gian kéo dài theo chính sách fixture: từ 7 ngày hoặc mô tả theo tuần/tháng',rule:'T1 · diễn tiến cần kiểm tra',text:'Triệu chứng đã kéo dài theo thông tin bạn cung cấp. Mình không chọn thuốc mạnh hơn hoặc tự chỉ liều. Mình đã chuyển ca cho dược sĩ mô phỏng để trao đổi về việc đi khám phù hợp. Nếu có dấu hiệu nguy hiểm, hãy tìm hỗ trợ cấp cứu ngay.'};
    if((f.age!==''&&(Number(f.age)<18||Number(f.age)>=65))||f.pregnancy==='yes'||/\bbe\b|con (minh|toi|em)|tre nho|nguoi gia|ba bau|ong (minh|toi)|ba (minh|toi)/.test(t)|| (f.conditions&&!/^(khong|khong co)$/i.test(normalize(f.conditions))) || (f.meds&&!/^(khong|khong co)$/i.test(normalize(f.meds))) || /tieu duong|benh nen|di ung|benh man|dang dung thuoc|u?ong thuoc.*(ngay|hom).*(khong do|khong khoi)|nhieu ngay|keo dai|loai manh hon/.test(t))return {route:'handoff',facts:f,reason:'Có yếu tố cần chuyên môn: nhóm dễ tổn thương, thuốc/bệnh nền hoặc triệu chứng kéo dài',rule:'T1 · người dùng thuốc & diễn tiến',text:'Mình chưa có đủ căn cứ để chọn sản phẩm an toàn cho người sẽ dùng thuốc. Mình đã chuyển ca cho dược sĩ mô phỏng, kèm thông tin hiện có và những mục chưa rõ. Chưa có gợi ý thuốc nào được gửi. Nếu xuất hiện dấu hiệu nguy hiểm, hãy đi cấp cứu ngay, đừng chờ chat.'};
    if(/con hang|ton kho|gia|khuyen mai|gan (minh|toi)|qua lay|chi nhanh/.test(t))return {route:'source',facts:f,reason:'Không có tool truy vấn tồn kho, giá hoặc chi nhánh trong fixture',rule:'T1 · nguồn sự thật',text:'Mình không có dữ liệu tồn kho, giá hay chi nhánh trong bản mô phỏng này, nên chưa thể xác nhận còn hàng. Bạn có thể nhờ dược sĩ kiểm tra. Đây chưa phải yêu cầu giữ hàng hay đặt mua.'};
    const known=/dau (rat )?hong|hong.*(dau|rat)|so mui|bi cam|bi ho|bi sot|nuoc muoi/.test(t);
    if(!known)return {route:'unknown',facts:f,reason:'Ca lạ ngoài tập luật mô phỏng; không đủ căn cứ phân loại',rule:'G10 · thu hẹp khi nghi ngờ',text:'Mình chưa hiểu đủ tình huống này để đưa ra gợi ý an toàn. Bạn cho biết ai sẽ dùng thuốc và độ tuổi được không? Bạn cũng có thể chuyển thẳng dược sĩ. Mình sẽ không đoán tên thuốc hoặc liều dùng.'};
    const missing=[];if(f.age==='')missing.push('tuổi người sẽ dùng thuốc');if(f.pregnancy==='unknown')missing.push('mang thai / cho con bú');if(!f.meds)missing.push('thuốc đang dùng và đã tự dùng');if(!f.conditions)missing.push('bệnh mạn tính / dị ứng');if(!f.duration)missing.push('thời gian triệu chứng');
    if(missing.length)return {route:'screen',facts:f,reason:`Chưa rõ: ${missing.join(', ')}`,rule:'T1 · sàng lọc trước gợi ý',text:'Để tránh nhầm người dùng thuốc, bạn cho biết ai sẽ dùng và bao nhiêu tuổi trước nhé? Bạn có thể bấm “Bổ sung thông tin” để cung cấp thêm thuốc đang dùng, bệnh mạn tính / dị ứng, mang thai / cho con bú và thời gian triệu chứng. Chưa đủ thông tin thì mình chưa gợi ý sản phẩm.'};
    return {route:'review',facts:f,reason:'Đã có các trường sàng lọc, vẫn cần dược sĩ kiểm tra tính phù hợp',rule:'T1 · gợi ý phải được dược sĩ duyệt',text:'Mình đã nhận đủ các mục sàng lọc bạn cung cấp. Một bản nháp đang chờ dược sĩ kiểm tra trước khi gửi; chưa có sản phẩm nào được gợi ý hoặc đặt mua. Bạn có thể sửa thông tin bất cứ lúc nào.'};
  }
  const api={classify,normalize,emptyFacts};if(typeof module!=='undefined')module.exports=api;root.VinMedEngine=api;
})(globalThis);
